from retry import retry_backoff

attempts = 0
@retry_backoff(retries=3, delay=0.01)
def flaky():
    global attempts
    attempts += 1
    if attempts < 3:
        raise ValueError('temp fail')
    return 'ok'

def test_flaky():
    assert flaky() == 'ok'

